#include <algorithm>
#include <cctype>
#include <map>
#include <string>
#include <vector>

class Palette
{
public:
    void add(const std::string& name) { m_names.push_back(name); }

    void ran(const std::string& name) { m_lastRun[name] = ++m_clock; }

    int score(const std::string& query, const std::string& name) const
    {
        std::string q;
        for (char c : query) if (c != ' ') q += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        if (q.empty()) return 0;
        int total{ 0 };
        std::size_t pos{ 0 };
        long previous{ -2 };
        for (char c : q)
        {
            std::size_t found{ std::string::npos };
            for (std::size_t i{ pos }; i < name.size(); ++i)
                if (std::tolower(static_cast<unsigned char>(name[i])) == c) { found = i; break; }
            if (found == std::string::npos) return -1;
            int s{ 1 };
            if (static_cast<long>(found) == previous + 1) s += 5;
            if (wordStart(name, found)) s += 8;
            total += s;
            previous = static_cast<long>(found);
            pos = found + 1;
        }
        return total;
    }

    std::vector<std::string> search(const std::string& query, std::size_t limit) const
    {
        struct Hit { std::string name; int score; long when; };
        std::vector<Hit> hits;
        for (const std::string& n : m_names)
        {
            const int s{ score(query, n) };
            if (s < 0) continue;
            const auto it{ m_lastRun.find(n) };
            hits.push_back({ n, s, it == m_lastRun.end() ? 0L : it->second });
        }
        std::sort(hits.begin(), hits.end(), [](const Hit& a, const Hit& b) {
            if (a.score != b.score) return a.score > b.score;
            if (a.when != b.when) return a.when > b.when;
            return a.name < b.name;
        });
        std::vector<std::string> out;
        for (std::size_t i{ 0 }; i < hits.size() && i < limit; ++i) out.push_back(hits[i].name);
        return out;
    }

private:
    static bool wordStart(const std::string& s, std::size_t i)
    {
        if (i == 0) return true;
        const char p{ s[i - 1] };
        if (p == ' ' || p == '/' || p == '_' || p == '-') return true;
        return std::isupper(static_cast<unsigned char>(s[i])) && std::islower(static_cast<unsigned char>(p));
    }

    std::vector<std::string> m_names;
    std::map<std::string, long> m_lastRun;
    long m_clock{ 0 };
};

