Palette make() { Palette p; for (const char* n : { "File/Save Level", "File/Save As", "View/Show Stats", "Edit/Select All", "Edit/saveLevelCopy" }) p.add(n); return p; }
TEST("scores") {
    const Palette p = make();
    CHECK_EQ(p.score("sl", "File/Save Level"), 18);
    CHECK_EQ(p.score("sl", "Edit/Select All"), 10);
    CHECK_EQ(p.score("fs", "File/Save As"), 18);
    CHECK_EQ(p.score("file", "File/Save As"), 9 + 6 + 6 + 6);
    CHECK_EQ(p.score("xyz", "File/Save As"), -1);
    CHECK_EQ(p.score("", "anything"), 0);
}
TEST("camelCase word starts") { const Palette p = make(); CHECK_EQ(p.score("sl", "Edit/saveLevelCopy"), 18); CHECK_EQ(p.score("lc", "Edit/saveLevelCopy"), 18); }
TEST("case and spaces ignored") { const Palette p = make(); CHECK_EQ(p.score("S L", "File/Save Level"), 18); }
TEST("search order") {
    const Palette p = make();
    CHECK_EQ(p.search("sl", 10), (std::vector<std::string>{ "Edit/saveLevelCopy", "File/Save Level", "Edit/Select All" }));
}
TEST("recency breaks ties") { Palette p = make(); p.ran("File/Save Level"); CHECK_EQ(p.search("sl", 2), (std::vector<std::string>{ "File/Save Level", "Edit/saveLevelCopy" })); }
TEST("empty query lists by recency") {
    Palette p = make(); p.ran("View/Show Stats"); p.ran("Edit/Select All");
    CHECK_EQ(p.search("", 3), (std::vector<std::string>{ "Edit/Select All", "View/Show Stats", "Edit/saveLevelCopy" }));
}

